def p(text, kind='Body'):
    text = text.replace('Ujjawal Upadhyay', 'Ujjwal Upadhyay')
    replacements = {
        'Table 2.1: Comparison with Related Solutions': 'Comparison of Related Solutions',
        'Table 2.2: Important Concepts': 'Important Concepts',
        'Table 3.1: Software Requirements': 'Software Requirements',
        'Table 3.2: Hardware Requirements': 'Hardware Requirements',
        'Table 3.3: Use Case Description - Register Account': 'Use Case Description - Register Account',
        'Table 3.4: Use Case Description - Send Friend Request': 'Use Case Description - Send Friend Request',
        'Table 3.5: Use Case Description - Real-Time Chat': 'Use Case Description - Real-Time Chat',
        'Table 3.6: Functional Requirements': 'Functional Requirements',
        'Table 4.1: User Collection Fields': 'User Collection Fields',
        'Table 4.2: FriendRequest Collection Fields': 'FriendRequest Collection Fields',
        'Table 4.3: Major API Route Groups': 'Major API Route Groups',
        'Table 4.4: Functional Test Cases': 'Functional Test Cases',
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return Paragraph(text, styles[kind])

class CoverPeople(Flowable):
    def __init__(self, students, guide):
        super().__init__()
        self.students = students
        self.guide = guide
    def wrap(self, avail_width, avail_height):
        self.width = avail_width
        return avail_width, 66
    def draw(self):
        c = self.canv
        c.setFont('Times-Bold', 14)
