story += [p('1.4 Objectives', 'Main')] + bullets(['To provide a secure platform for language learners to connect with other learners.', 'To enable real-time chat and video communication for practical language use.', 'To use AI for language questions, translation, and language detection.', 'To store user and relationship data safely using MongoDB.', 'To implement a responsive and easy-to-use web interface.']) + [p('1.5 Scope of the Project', 'Main'), p('The implemented scope covers user authentication, profile onboarding, recommendations, friend requests, real-time chat, video calling, theme selection, and AI support. The system is intended for individuals who want to learn or practice languages through direct interaction. It does not claim to replace a formal language course or certified assessment. A language-level test and self-assessment module is considered a future extension rather than a completed feature.', 'Body'), p('1.6 Organization of the Report', 'Main'), p('Chapter 1 introduces the problem and proposed solution. Chapter 2 reviews related solutions and presents the development methodology. Chapter 3 explains requirements, analysis models, and architecture. Chapter 4 describes implementation, database design, modules, and testing. Chapter 5 presents conclusions, limitations, and future scope.', 'Body'), PageBreak()]

