story += [p('CHAPTER 2', 'CoverTitle'), p('LITERATURE SURVEY', 'CoverTitle'), p('2.1 Existing Solutions', 'Main'), p('A review of related platforms was carried out to understand the features available for language learning, social connection, and real-time communication. The study focused on well-known language-exchange and communication products rather than copying their designs. Each product offers useful capabilities, but none is identical to the proposed system.', 'Body'), grid([['Existing Solution','Strengths','Gap Addressed by EchoChat'],['Tandem','Language partner discovery, text and voice interaction.','EchoChat combines friend workflow with Stream-based chat, video, and Gemini support.'],['HelloTalk','Large language-learning community and translation tools.','EchoChat focuses on a smaller, direct web workflow and AI assistance through its own backend.'],['Duolingo','Structured lessons and gamified practice.','EchoChat emphasizes interaction with other people rather than pre-defined lessons.'],['Discord','Communities, text and voice channels.','EchoChat provides learner profiles and language-oriented discovery.'],['WhatsApp / Telegram','Fast messaging and calling.','EchoChat connects communication with language preferences and AI language help.']], [1.25*inch,2.35*inch,2.9*inch]), p('Table 2.1: Comparison with Related Solutions', 'Caption'), PageBreak()]
story += [p('2.1.1 Literature Gap', 'Sub'), p('The review shows that language-learning applications, messaging applications, and AI assistants often work as separate products. A learner may use one product to find people, another for calling, and a third for translation. This creates context switching and does not provide one consistent learning workflow. EchoChat is undertaken to combine learner profile data, social connection, real-time communication, and AI help in one web application.', 'Body'), p('2.2 Methodology', 'Main'), p('The project follows an iterative web-development methodology. Requirements were identified from the needs of language learners. The system was then divided into frontend, backend, database, real-time communication, and AI modules. Each module was developed and tested independently before integration.', 'Body')]
