story += [p('The frontend is responsible for user interaction, page navigation, server-state handling, and local theme state. The Express backend validates requests, verifies JWT authentication, coordinates business logic, reads or writes MongoDB data, generates Stream user tokens, and sends AI requests to Gemini. The separation ensures that server secrets remain outside the browser.', 'Body'), p('3.4.2 Architectural Strategy', 'Sub'), p('The project follows an MVC-inspired backend structure. Routes receive HTTP requests and invoke controllers. Controllers contain feature-specific logic. Mongoose models define data schemas and database interaction. Middleware protects private endpoints. The frontend consumes REST APIs and uses specialized external services only through secure integration points.', 'Body'), PageBreak()]
story += [p('3.4.3 Sequence Diagram: Login and Profile Access', 'Sub')]
